final_template:
AWSTemplateFormatVersion: '2010-09-09'
Description: >-
  Self-contained AWS AppSync GraphQL API "TodoAPIwithJs" with API key
  authentication, a DynamoDB todos table with an owner-index global secondary
  index, JavaScript (APPSYNC_JS) pipeline resolvers for create/update/delete/get/list
  plus a by-owner query, and real-time create/update/delete subscriptions.

Resources:

  # ---------------------------------------------------------------------------
  # DynamoDB table
  # ---------------------------------------------------------------------------
  TodoTable:
    Type: AWS::DynamoDB::Table
    DeletionPolicy: Retain
    UpdateReplacePolicy: Retain
    Properties:
      BillingMode: PAY_PER_REQUEST
      AttributeDefinitions:
        - AttributeName: id
          AttributeType: S
        - AttributeName: owner
          AttributeType: S
        - AttributeName: createdAt
          AttributeType: S
      KeySchema:
        - AttributeName: id
          KeyType: HASH
      GlobalSecondaryIndexes:
        - IndexName: owner-index
          KeySchema:
            - AttributeName: owner
              KeyType: HASH
            - AttributeName: createdAt
              KeyType: RANGE
          Projection:
            ProjectionType: ALL
      SSESpecification:
        SSEEnabled: true
      PointInTimeRecoverySpecification:
        PointInTimeRecoveryEnabled: true

  # ---------------------------------------------------------------------------
  # IAM roles
  # ---------------------------------------------------------------------------
  AppSyncCloudWatchLogsRole:
    Type: AWS::IAM::Role
    Properties:
      AssumeRolePolicyDocument:
        Version: '2012-10-17'
        Statement:
          - Effect: Allow
            Principal:
              Service:
                - !Sub 'appsync.${AWS::URLSuffix}'
            Action:
              - sts:AssumeRole
      Policies:
        - PolicyName: AppSyncPushToCloudWatchLogs
          PolicyDocument:
            Version: '2012-10-17'
            Statement:
              - Effect: Allow
                Action:
                  - logs:CreateLogGroup
                  - logs:CreateLogStream
                  - logs:PutLogEvents
                Resource:
                  - !Sub 'arn:${AWS::Partition}:logs:${AWS::Region}:${AWS::AccountId}:log-group:/aws/appsync/apis/*'
                  - !Sub 'arn:${AWS::Partition}:logs:${AWS::Region}:${AWS::AccountId}:log-group:/aws/appsync/apis/*:*'

  AppSyncDynamoDBRole:
    Type: AWS::IAM::Role
    Properties:
      AssumeRolePolicyDocument:
        Version: '2012-10-17'
        Statement:
          - Effect: Allow
            Principal:
              Service:
                - !Sub 'appsync.${AWS::URLSuffix}'
            Action:
              - sts:AssumeRole
      Policies:
        - PolicyName: AppSyncTodoTableAccess
          PolicyDocument:
            Version: '2012-10-17'
            Statement:
              - Sid: TodoTableCrud
                Effect: Allow
                Action:
                  - dynamodb:GetItem
                  - dynamodb:PutItem
                  - dynamodb:UpdateItem
                  - dynamodb:DeleteItem
                  - dynamodb:Query
                  - dynamodb:Scan
                Resource:
                  - !GetAtt TodoTable.Arn
                  - !Sub '${TodoTable.Arn}/index/*'

  # ---------------------------------------------------------------------------
  # AppSync API, schema, API key and data sources
  # ---------------------------------------------------------------------------
  GraphQLApi:
    Type: AWS::AppSync::GraphQLApi
    Properties:
      Name: TodoAPIwithJs
      AuthenticationType: API_KEY
      XrayEnabled: true
      LogConfig:
        CloudWatchLogsRoleArn: !GetAtt AppSyncCloudWatchLogsRole.Arn
        FieldLogLevel: ALL
        ExcludeVerboseContent: false

  GraphQLSchema:
    Type: AWS::AppSync::GraphQLSchema
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      Definition: |
        type Todo {
          id: ID!
          name: String
          description: String
          owner: String
          createdAt: String
          updatedAt: String
        }

        input TodoInput {
          id: ID
          name: String
          description: String
          owner: String
          createdAt: String
          updatedAt: String
        }

        type Query {
          getTodo(id: ID!): Todo
          listTodos: [Todo]
          todosByOwner(owner: String!): [Todo]
        }

        type Mutation {
          addTodo(input: TodoInput!): Todo
          updateTodo(input: TodoInput!): Todo
          deleteTodo(id: ID!): Todo
        }

        type Subscription {
          onCreateTodo: Todo
            @aws_subscribe(mutations: ["addTodo"])
          onUpdateTodo: Todo
            @aws_subscribe(mutations: ["updateTodo"])
          onDeleteTodo: Todo
            @aws_subscribe(mutations: ["deleteTodo"])
        }

        schema {
          query: Query
          mutation: Mutation
          subscription: Subscription
        }

  ApiKey:
    Type: AWS::AppSync::ApiKey
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      Description: API key for the TodoAPIwithJs GraphQL API
      Expires: 2524608000

  TodoDataSource:
    Type: AWS::AppSync::DataSource
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      Name: TodoTableDataSource
      Description: DynamoDB data source for the todos table
      Type: AMAZON_DYNAMODB
      ServiceRoleArn: !GetAtt AppSyncDynamoDBRole.Arn
      DynamoDBConfig:
        TableName: !Ref TodoTable
        AwsRegion: !Ref 'AWS::Region'

  NoneDataSource:
    Type: AWS::AppSync::DataSource
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      Name: NoneDataSource
      Description: Local NONE data source used by the subscription resolvers
      Type: NONE

  # ---------------------------------------------------------------------------
  # JavaScript (APPSYNC_JS) functions - one per data operation
  # ---------------------------------------------------------------------------
  GetTodoFunction:
    Type: AWS::AppSync::FunctionConfiguration
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      Name: GetTodo
      Description: Retrieve a single Todo item by id
      DataSourceName: !GetAtt TodoDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          return {
            operation: 'GetItem',
            key: util.dynamodb.toMapValues({ id: ctx.args.id }),
          };
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          return ctx.result;
        }

  ListTodosFunction:
    Type: AWS::AppSync::FunctionConfiguration
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      Name: ListTodos
      Description: List every Todo item
      DataSourceName: !GetAtt TodoDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          return { operation: 'Scan' };
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          if (!ctx.result || !ctx.result.items) {
            return [];
          }
          return ctx.result.items;
        }

  QueryTodosByOwnerFunction:
    Type: AWS::AppSync::FunctionConfiguration
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      Name: QueryTodosByOwner
      Description: Query the owner-index global secondary index for a given owner
      DataSourceName: !GetAtt TodoDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          return {
            operation: 'Query',
            index: 'owner-index',
            query: {
              expression: '#owner = :owner',
              expressionNames: { '#owner': 'owner' },
              expressionValues: { ':owner': util.dynamodb.toDynamoDB(ctx.args.owner) },
            },
            scanIndexForward: true,
          };
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          if (!ctx.result || !ctx.result.items) {
            return [];
          }
          return ctx.result.items;
        }

  PutTodoFunction:
    Type: AWS::AppSync::FunctionConfiguration
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      Name: PutTodo
      Description: Persist a fully populated Todo item
      DataSourceName: !GetAtt TodoDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const item = ctx.prev.result;
          return {
            operation: 'PutItem',
            key: util.dynamodb.toMapValues({ id: item.id }),
            attributeValues: util.dynamodb.toMapValues(item),
          };
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          return ctx.result;
        }

  UpdateTodoFunction:
    Type: AWS::AppSync::FunctionConfiguration
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      Name: UpdateTodo
      Description: Update an existing Todo item by id
      DataSourceName: !GetAtt TodoDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const item = ctx.prev.result;
          const expressionNames = {};
          const expressionValues = {};
          const sets = [];

          Object.keys(item).forEach((key) => {
            if (key === 'id') {
              return;
            }
            const nameKey = '#' + key;
            const valueKey = ':' + key;
            expressionNames[nameKey] = key;
            expressionValues[valueKey] = util.dynamodb.toDynamoDB(item[key]);
            sets.push(nameKey + ' = ' + valueKey);
          });

          return {
            operation: 'UpdateItem',
            key: util.dynamodb.toMapValues({ id: item.id }),
            update: {
              expression: 'SET ' + sets.join(', '),
              expressionNames: expressionNames,
              expressionValues: expressionValues,
            },
          };
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          return ctx.result;
        }

  DeleteTodoFunction:
    Type: AWS::AppSync::FunctionConfiguration
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      Name: DeleteTodo
      Description: Delete a Todo item by id
      DataSourceName: !GetAtt TodoDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          return {
            operation: 'DeleteItem',
            key: util.dynamodb.toMapValues({ id: ctx.prev.result.id }),
          };
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          return ctx.result;
        }

  # ---------------------------------------------------------------------------
  # Query pipeline resolvers
  # ---------------------------------------------------------------------------
  GetTodoResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: GraphQLSchema
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      TypeName: Query
      FieldName: getTodo
      Kind: PIPELINE
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      PipelineConfig:
        Functions:
          - !GetAtt GetTodoFunction.FunctionId
      Code: |
        export function request(ctx) {
          return {};
        }

        export function response(ctx) {
          return ctx.result;
        }

  ListTodosResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: GraphQLSchema
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      TypeName: Query
      FieldName: listTodos
      Kind: PIPELINE
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      PipelineConfig:
        Functions:
          - !GetAtt ListTodosFunction.FunctionId
      Code: |
        export function request(ctx) {
          return {};
        }

        export function response(ctx) {
          return ctx.result;
        }

  TodosByOwnerResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: GraphQLSchema
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      TypeName: Query
      FieldName: todosByOwner
      Kind: PIPELINE
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      PipelineConfig:
        Functions:
          - !GetAtt QueryTodosByOwnerFunction.FunctionId
      Code: |
        export function request(ctx) {
          return {};
        }

        export function response(ctx) {
          return ctx.result;
        }

  # ---------------------------------------------------------------------------
  # Mutation pipeline resolvers
  # ---------------------------------------------------------------------------
  AddTodoResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: GraphQLSchema
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      TypeName: Mutation
      FieldName: addTodo
      Kind: PIPELINE
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      PipelineConfig:
        Functions:
          - !GetAtt PutTodoFunction.FunctionId
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const input = ctx.args.input;
          const now = util.time.nowISO8601();
          let owner = input.owner;
          if (!owner) {
            owner = (ctx.identity && ctx.identity.username) || 'anonymous';
          }
          return {
            id: input.id || util.autoId(),
            name: input.name || null,
            description: input.description || null,
            owner: owner,
            createdAt: input.createdAt || now,
            updatedAt: input.updatedAt || now,
          };
        }

        export function response(ctx) {
          return ctx.result;
        }

  UpdateTodoResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: GraphQLSchema
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      TypeName: Mutation
      FieldName: updateTodo
      Kind: PIPELINE
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      PipelineConfig:
        Functions:
          - !GetAtt UpdateTodoFunction.FunctionId
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const input = ctx.args.input;
          const item = { id: input.id };
          if (input.name !== undefined) {
            item.name = input.name;
          }
          if (input.description !== undefined) {
            item.description = input.description;
          }
          if (input.owner !== undefined) {
            item.owner = input.owner;
          }
          if (input.createdAt !== undefined) {
            item.createdAt = input.createdAt;
          }
          item.updatedAt = util.time.nowISO8601();
          return item;
        }

        export function response(ctx) {
          return ctx.result;
        }

  DeleteTodoResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: GraphQLSchema
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      TypeName: Mutation
      FieldName: deleteTodo
      Kind: PIPELINE
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      PipelineConfig:
        Functions:
          - !GetAtt DeleteTodoFunction.FunctionId
      Code: |
        export function request(ctx) {
          return { id: ctx.args.id };
        }

        export function response(ctx) {
          return ctx.result;
        }

  # ---------------------------------------------------------------------------
  # Subscription resolvers (NONE data source, payload forwarded from mutation)
  # ---------------------------------------------------------------------------
  OnCreateTodoResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: GraphQLSchema
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      TypeName: Subscription
      FieldName: onCreateTodo
      DataSourceName: !GetAtt NoneDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        export function request(ctx) {
          return {};
        }

        export function response(ctx) {
          return ctx.result;
        }

  OnUpdateTodoResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: GraphQLSchema
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      TypeName: Subscription
      FieldName: onUpdateTodo
      DataSourceName: !GetAtt NoneDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        export function request(ctx) {
          return {};
        }

        export function response(ctx) {
          return ctx.result;
        }

  OnDeleteTodoResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: GraphQLSchema
    Properties:
      ApiId: !GetAtt GraphQLApi.ApiId
      TypeName: Subscription
      FieldName: onDeleteTodo
      DataSourceName: !GetAtt NoneDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        export function request(ctx) {
          return {};
        }

        export function response(ctx) {
          return ctx.result;
        }

Outputs:
  GraphQLApiId:
    Description: AppSync GraphQL API identifier
    Value: !GetAtt GraphQLApi.ApiId

  GraphQLApiUrl:
    Description: AppSync GraphQL API endpoint URL
    Value: !GetAtt GraphQLApi.GraphQLUrl

  GraphQLApiArn:
    Description: AppSync GraphQL API ARN
    Value: !GetAtt GraphQLApi.Arn

  ApiKeyId:
    Description: AppSync API key identifier
    Value: !Ref ApiKey

  TodoTableName:
    Description: Name of the DynamoDB todos table
    Value: !Ref TodoTable

AWSTemplateFormatVersion: '2010-09-09'
Description: >
  SimpleTodoAPI - an AWS AppSync GraphQL API (API key auth, suitable for development and
  testing only) backed by a single Amazon DynamoDB table. The template creates every
  dependency it needs: the DynamoDB table (with an owner secondary index), the AppSync
  service role with least-privilege DynamoDB access, the GraphQL schema, one DynamoDB
  data source and six APPSYNC_JS (JavaScript) unit resolvers for createTodo, updateTodo,
  deleteTodo, getTodo, listTodos and todosByOwner.

Metadata:
  AWS::CloudFormation::Interface:
    ParameterGroups:
      - Label:
          default: API Configuration
        Parameters:
          - ApiName

Parameters:
  ApiName:
    Type: String
    Default: SimpleTodoAPI
    MinLength: 1
    MaxLength: 128
    Description: Name of the AppSync GraphQL API (defaults to SimpleTodoAPI).

Resources:

  # ---------------------------------------------------------------------------
  # DynamoDB table for to-do items (no hardcoded name so the stack can be
  # re-created without collisions) plus the owner secondary index.
  # Retain policies keep the to-do data if the stack is deleted/replaced.
  # ---------------------------------------------------------------------------
  TodosTable:
    Type: AWS::DynamoDB::Table
    DeletionPolicy: Retain
    UpdateReplacePolicy: Retain
    Properties:
      BillingMode: PAY_PER_REQUEST
      AttributeDefinitions:
        - AttributeName: id
          AttributeType: S
        - AttributeName: owner
          AttributeType: S
      KeySchema:
        - AttributeName: id
          KeyType: HASH
      GlobalSecondaryIndexes:
        - IndexName: owner-index
          KeySchema:
            - AttributeName: owner
              KeyType: HASH
          Projection:
            ProjectionType: ALL
      Tags:
        - Key: Name
          Value: !Sub '${AWS::StackName}-todos'

  # ---------------------------------------------------------------------------
  # Service role that AppSync assumes to read/write only this table and index.
  # ---------------------------------------------------------------------------
  AppSyncServiceRole:
    Type: AWS::IAM::Role
    Properties:
      RoleName: !Sub '${AWS::StackName}-appsync-todo-role'
      Description: Service role assumed by AppSync to access the todos table.
      AssumeRolePolicyDocument:
        Version: '2012-10-17'
        Statement:
          - Effect: Allow
            Principal:
              Service: appsync.amazonaws.com
            Action: sts:AssumeRole
      Policies:
        - PolicyName: !Sub '${AWS::StackName}-appsync-todo-dynamodb'
          PolicyDocument:
            Version: '2012-10-17'
            Statement:
              - Sid: TodosTableAccess
                Effect: Allow
                Action:
                  - dynamodb:GetItem
                  - dynamodb:PutItem
                  - dynamodb:UpdateItem
                  - dynamodb:DeleteItem
                  - dynamodb:Query
                  - dynamodb:Scan
                Resource:
                  - !GetAtt TodosTable.Arn
                  - !Sub '${TodosTable.Arn}/index/*'
      Tags:
        - Key: Name
          Value: !Sub '${AWS::StackName}-appsync-todo-role'

  # ---------------------------------------------------------------------------
  # GraphQL API. API key auth is the only mode here, which keeps manual testing
  # trivial but is NOT a production choice (see notes at the bottom).
  # ---------------------------------------------------------------------------
  TodoApi:
    Type: AWS::AppSync::GraphQLApi
    Properties:
      Name: !Ref ApiName
      AuthenticationType: API_KEY
      XrayEnabled: true
      Tags:
        - Key: Name
          Value: !Ref ApiName

  # API keys are intended for development/testing only. Expires is intentionally
  # omitted so the 7-day default applies (AppSync caps key lifetime at 365 days).
  TodoApiKey:
    Type: AWS::AppSync::ApiKey
    Properties:
      ApiId: !GetAtt TodoApi.ApiId
      Description: Development/testing API key for SimpleTodoAPI - do not use in production.

  # ---------------------------------------------------------------------------
  # GraphQL schema, inlined as a literal block (no external S3 file).
  # ---------------------------------------------------------------------------
  TodoApiSchema:
    Type: AWS::AppSync::GraphQLSchema
    Properties:
      ApiId: !GetAtt TodoApi.ApiId
      Definition: |
        schema {
          query: Query
          mutation: Mutation
        }

        type Todo {
          id: ID!
          owner: String!
          title: String!
          description: String
          status: String
          completed: Boolean
          createdAt: AWSDateTime
          updatedAt: AWSDateTime
        }

        input CreateTodoInput {
          id: ID
          owner: String!
          title: String!
          description: String
          status: String
          completed: Boolean
        }

        input UpdateTodoInput {
          id: ID!
          owner: String
          title: String
          description: String
          status: String
          completed: Boolean
        }

        type Query {
          getTodo(id: ID!): Todo
          listTodos: [Todo]
          todosByOwner(owner: String!): [Todo]
        }

        type Mutation {
          createTodo(input: CreateTodoInput!): Todo
          updateTodo(input: UpdateTodoInput!): Todo
          deleteTodo(id: ID!): Todo
        }

  # ---------------------------------------------------------------------------
  # Single DynamoDB data source shared by all six resolvers.
  # ---------------------------------------------------------------------------
  TodosDataSource:
    Type: AWS::AppSync::DataSource
    Properties:
      ApiId: !GetAtt TodoApi.ApiId
      Name: TodosDynamoDBDataSource
      Description: DynamoDB data source for the todos table.
      Type: AMAZON_DYNAMODB
      ServiceRoleArn: !GetAtt AppSyncServiceRole.Arn
      DynamoDBConfig:
        TableName: !Ref TodosTable
        AwsRegion: !Ref 'AWS::Region'
        UseCallerCredentials: false

  # ---------------------------------------------------------------------------
  # Resolvers - JavaScript (APPSYNC_JS) runtime, no VTL templates.
  # ---------------------------------------------------------------------------
  CreateTodoResolver:
    Type: AWS::AppSync::Resolver
    Properties:
      ApiId: !GetAtt TodoApi.ApiId
      TypeName: Mutation
      FieldName: createTodo
      DataSourceName: !GetAtt TodosDataSource.Name
      Kind: UNIT
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const input = ctx.args.input;
          if (!input) {
            util.error('Missing required argument: input', 'BadRequest');
          }
          if (!input.owner || !input.title) {
            util.error('The fields owner and title are required', 'BadRequest');
          }

          const now = util.time.nowISO8601();
          const item = {
            id: input.id ? String(input.id) : util.autoId(),
            owner: String(input.owner),
            title: String(input.title),
            status: input.status ? String(input.status) : 'PENDING',
            completed: input.completed === true,
            createdAt: now,
            updatedAt: now,
          };
          if (input.description !== undefined && input.description !== null) {
            item.description = String(input.description);
          }

          return {
            operation: 'PutItem',
            key: util.dynamodb.toMapValues({ id: item.id }),
            attributeValues: util.dynamodb.toMapValues(item),
          };
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          return ctx.result;
        }

  UpdateTodoResolver:
    Type: AWS::AppSync::Resolver
    Properties:
      ApiId: !GetAtt TodoApi.ApiId
      TypeName: Mutation
      FieldName: updateTodo
      DataSourceName: !GetAtt TodosDataSource.Name
      Kind: UNIT
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const input = ctx.args.input;
          if (!input || !input.id) {
            util.error('The field id is required', 'BadRequest');
          }

          const sets = [];
          const expressionNames = {};
          const expressionValues = {};

          const assign = (field, value) => {
            const nameKey = '#' + field;
            const valueKey = ':' + field;
            expressionNames[nameKey] = field;
            expressionValues[valueKey] = util.dynamodb.toDynamoDB(value);
            sets.push(nameKey + ' = ' + valueKey);
          };

          if (input.owner !== undefined && input.owner !== null) {
            assign('owner', String(input.owner));
          }
          if (input.title !== undefined && input.title !== null) {
            assign('title', String(input.title));
          }
          if (input.description !== undefined && input.description !== null) {
            assign('description', String(input.description));
          }
          if (input.status !== undefined && input.status !== null) {
            assign('status', String(input.status));
          }
          if (input.completed !== undefined && input.completed !== null) {
            assign('completed', input.completed === true);
          }

          assign('updatedAt', util.time.nowISO8601());

          return {
            operation: 'UpdateItem',
            key: util.dynamodb.toMapValues({ id: String(input.id) }),
            update: {
              expression: 'SET ' + sets.join(', '),
              expressionNames: expressionNames,
              expressionValues: expressionValues,
            },
            condition: {
              expression: 'attribute_exists(#id)',
              expressionNames: { '#id': 'id' },
            },
          };
        }

        export function response(ctx) {
          if (ctx.error) {
            if (ctx.error.type === 'DynamoDB:ConditionalCheckFailedException') {
              util.error('Todo not found', 'NotFound');
            }
            util.error(ctx.error.message, ctx.error.type);
          }
          return ctx.result;
        }

  DeleteTodoResolver:
    Type: AWS::AppSync::Resolver
    Properties:
      ApiId: !GetAtt TodoApi.ApiId
      TypeName: Mutation
      FieldName: deleteTodo
      DataSourceName: !GetAtt TodosDataSource.Name
      Kind: UNIT
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const id = ctx.args.id;
          if (!id) {
            util.error('The field id is required', 'BadRequest');
          }

          return {
            operation: 'DeleteItem',
            key: util.dynamodb.toMapValues({ id: String(id) }),
            condition: {
              expression: 'attribute_exists(#id)',
              expressionNames: { '#id': 'id' },
            },
          };
        }

        export function response(ctx) {
          if (ctx.error) {
            if (ctx.error.type === 'DynamoDB:ConditionalCheckFailedException') {
              util.error('Todo not found', 'NotFound');
            }
            util.error(ctx.error.message, ctx.error.type);
          }
          return ctx.result;
        }

  GetTodoResolver:
    Type: AWS::AppSync::Resolver
    Properties:
      ApiId: !GetAtt TodoApi.ApiId
      TypeName: Query
      FieldName: getTodo
      DataSourceName: !GetAtt TodosDataSource.Name
      Kind: UNIT
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const id = ctx.args.id;
          if (!id) {
            util.error('The field id is required', 'BadRequest');
          }

          return {
            operation: 'GetItem',
            key: util.dynamodb.toMapValues({ id: String(id) }),
          };
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          if (ctx.result === null || ctx.result === undefined) {
            util.error('Todo not found', 'NotFound');
          }
          return ctx.result;
        }

  ListTodosResolver:
    Type: AWS::AppSync::Resolver
    Properties:
      ApiId: !GetAtt TodoApi.ApiId
      TypeName: Query
      FieldName: listTodos
      DataSourceName: !GetAtt TodosDataSource.Name
      Kind: UNIT
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          return {
            operation: 'Scan',
          };
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          return ctx.result.items;
        }

  TodosByOwnerResolver:
    Type: AWS::AppSync::Resolver
    Properties:
      ApiId: !GetAtt TodoApi.ApiId
      TypeName: Query
      FieldName: todosByOwner
      DataSourceName: !GetAtt TodosDataSource.Name
      Kind: UNIT
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: '1.0.0'
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const owner = ctx.args.owner;
          if (!owner) {
            util.error('The field owner is required', 'BadRequest');
          }

          return {
            operation: 'Query',
            index: 'owner-index',
            query: {
              expression: '#owner = :owner',
              expressionNames: { '#owner': 'owner' },
              expressionValues: { ':owner': util.dynamodb.toDynamoDB(String(owner)) },
            },
          };
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          return ctx.result.items;
        }

# NOTE ON API-KEY AUTHENTICATION
# API keys are accepted here only to keep a test to-do API simple to exercise.
# They are not a production choice. A follow-up template should add additional
# authorization modes (Cognito User Pools and/or IAM) on AWS::AppSync::GraphQLApi,
# enforce per-owner authorization inside the resolvers, and enable request/field
# level logging (AWS::AppSync::GraphQLApi LogConfig) if auditing is required.

Outputs:
  GraphQLApiUrl:
    Description: AppSync GraphQL endpoint used for queries and mutations.
    Value: !GetAtt TodoApi.GraphQLUrl

  GraphQLApiId:
    Description: AppSync GraphQL API identifier.
    Value: !GetAtt TodoApi.ApiId

  GraphQLApiArn:
    Description: AppSync GraphQL API ARN.
    Value: !GetAtt TodoApi.Arn

  # Security trade-off: CloudFormation Outputs are readable by anyone with stack
  # read access, so exposing the API key here is convenient for testing but leaks
  # the credential. Prefer retrieving it from the console/CLI if that matters.
  ApiKey:
    Description: Generated API key for the SimpleTodoAPI (development/testing only).
    Value: !GetAtt TodoApiKey.ApiKey

  TodosTableName:
    Description: Name of the DynamoDB table that stores to-do items.
    Value: !Ref TodosTable
